--[[
    Super Timeline 的一种通用脚本; 
    内含一种特殊 clip, 它会一直 loop, 直到对应的 碰撞体被点击了, 然后跳入对应的 next clip:

    请在每个 nextClipInfo.conditionKey 内写入触发播放 clip 的 碰撞体的 id str, 比如 "head", "ear", "chest";

]]--

---@class SuperTimeline_LoopAndWaitTouch           
local SuperTimeline_LoopAndWaitTouch = Class('SuperTimeline_LoopAndWaitTouch')



-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Mathf = CS.UnityEngine.Mathf
local Vector3 = CS.UnityEngine.Vector3
local Input = CS.UnityEngine.Input
local KeyCode = CS.UnityEngine.KeyCode
local Time = CS.UnityEngine.Time

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


local IdolLive3D_Utils = import('Game.IdolLive3D.IdolLive3D_Utils')

---@type IdolLive3D_States
local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')


-- ========================================================


local effectiveDuration = 0.1 -- 长度为: 若干帧frame


-- ========================================================

---@param idolLive3D_SuperTimeLineState_ table
function SuperTimeline_LoopAndWaitTouch:__init( idolLive3D_SuperTimeLineState_ )
    
    self.idolLive3D_SuperTimeLineState = idolLive3D_SuperTimeLineState_
    self.lastClipId = nil
    self.lastRefreshTime = 0
    self.nextClipInfosMap = {}

    self.EventSimpleTapInAnyTime  = Events.AddListener(IdolLive3D_States.EventSimpleTapInAnyTime, Bind(self, self._OnSimpleTapInAnyTime))
end




-- 需手动调用 Delete()
function SuperTimeline_LoopAndWaitTouch:__delete()
    --printError( "SuperTimeline_LoopAndWaitTouch:__delete" )
    if self.EventSimpleTapInAnyTime then
        Events.RemoveListener(IdolLive3D_States.EventSimpleTapInAnyTime, self.EventSimpleTapInAnyTime)
        self.EventSimpleTapInAnyTime = nil
    end
end


---@param clipJson_ table @ c# class SuperTimelineClip 内数据
---@param timelineStateEnv_ table
function SuperTimeline_LoopAndWaitTouch:CheckEachFrame( clipJson_, timelineStateEnv_ ) 
    assert( table.count(clipJson_.nextClipInfos) > 0 )

    self.lastRefreshTime = Time.time
    if clipJson_.clipId ~= self.lastClipId then 
        -- 说明是切换 clip 的第一帧:
        self.nextClipInfosMap = {}
        for _,nextClipInfo in pairs(clipJson_.nextClipInfos) do 
            assert( string.isEmpty(nextClipInfo.conditionKey) == false )
            self.nextClipInfosMap[string.lower(nextClipInfo.conditionKey)] = nextClipInfo
        end
        ---
        self.lastClipId = clipJson_.clipId
    end     
end



---@param idStr_ string @ role 碰撞体 ID组件的 string 参数
function SuperTimeline_LoopAndWaitTouch:_OnSimpleTapInAnyTime( idStr_ )
    if (Time.time - self.lastRefreshTime) > effectiveDuration then 
        --printError("不在有效时间窗口内")
        return
    end 
    ---
    local touchStr = tostring(idStr_)
    local nextClipInfo = self.nextClipInfosMap[string.lower(touchStr)]
    if isNotNull(nextClipInfo) then 
        --printError("条件 跳入下一个 clip id: " .. tostring(nextClipInfo.clipId) )
        self.idolLive3D_SuperTimeLineState:PlayClip( nextClipInfo.clipId, false )
    else 
        --printError("点击了没有配进 nextClipInfos 的碰撞体 str = " .. tostring(touchStr) )
    end 
end




return SuperTimeline_LoopAndWaitTouch
